14	function useMeasure(): [React.RefObject<HTMLDivElement | null>, number] {
15	  const ref = useRef<HTMLDivElement>(null);
16	  const [w, setW] = useState(0);
17	  useEffect(() => {
18	    if (!ref.current) return;
19	    const ro = new ResizeObserver(es => { for (const e of es) setW(e.contentRect.width); });
20	    ro.observe(ref.current);
21	    return () => ro.disconnect();
22	  }, []);
23	  return [ref, w];
24	}
