108	  const xFor = (frame: number) => ((frame - 1) / fps) * pxPerSec;
109	
110	  const fitPx = scrollW > 0 ? scrollW / Math.max(duration, 1) : 2.2;
111	  const pxPerSec = fitPx * zoom;
112	  const W = duration * pxPerSec;
113	  const spansTop = TL.ruler + TL.round + TL.state;
114	  const lanesTop = spansTop + TL.span * 2;
115	  const totalH = lanesTop + TL.lane * 2;
