118	  // Live edge being dragged, so the block redraws smoothly before the PUT commits.
119	  const dragRef = useRef<{ id: number; edge: 'start' | 'end' } | null>(null);
120	  const [dragFrame, setDragFrame] = useState<number | null>(null);
121	
122	  const fil = (e: Event) => matchFilter(categoryForAction(e.action), filter);
123	  const redEv = events.filter(e => laneFor(e) === 'red' && e.action !== 'fight_end' && fil(e));
124	  const blueEv = events.filter(e => laneFor(e) === 'blue' && e.action !== 'fight_end' && fil(e));
125	  const roundEv = events.filter(e => categoryForAction(e.action) === 'round' || e.action === 'fight_end');
126	  // Everything after fight_end is dead air (celebration, doctor check, corner
127	  // talk) — the round span and the last state segment are visually capped
128	  // here to end there, so the timeline actually looks like the fight is
129	  // over. The underlying round span's real end_frame is untouched (only the
130	  // auto-created `excluded` span makes the tail harmless for scoring/export
131	  // — see Annotate.tsx's confirmFightEnd); this is display-only.
132	  const fightEndFrame = events.find(e => e.action === 'fight_end')?.frame ?? null;
133	  const stateEv = useMemo(
134	    () => events.filter(e => categoryForAction(e.action) === 'state').sort((a, b) => a.frame - b.frame),
135	    [events],
136	  );
137	  const segs = stateEv
138	    .map((e, i) => {
139	      const rawT1 = i + 1 < stateEv.length ? (stateEv[i + 1].frame - 1) / fps : duration;
140	      const t1 = fightEndFrame != null ? Math.min(rawT1, (fightEndFrame - 1) / fps) : rawT1;
141	      return {
142	        id: e.id,
143	        t0: (e.frame - 1) / fps,
144	        t1,
145	        state: e.action === 'state_clinch' ? 'CLINCH' : e.action === 'state_ground' ? 'GROUND' : 'STRIKING',
146	      };
147	    })
148	    .filter(s => s.t1 >= s.t0); // drop a segment that starts entirely after fight_end
149	
150	  // Same display-only capping as the state segments above: the round block
151	  // that contains fight_end is drawn ending there instead of at its real
152	  // (now-stale) end_frame. Edge-drag still targets the real span by id, so
